import { useEffect, useState } from 'react';
import { useAuth } from '../../context/AuthContext';
import { getStudentEnrollments, getStudentAssignments, getStudentProgress } from '../../api';
import { MetricCard, ProgressBar, Badge, Card, SectionTitle, Spinner, gradeVariant } from '../../components/UI';
import { BookOpen, ClipboardList, Brain, TrendingUp } from 'lucide-react';

export default function StudentDashboard() {
  const { user } = useAuth();
  const [enrollments, setEnrollments] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [progress,    setProgress]    = useState([]);
  const [loading,     setLoading]     = useState(true);

  useEffect(() => {
    Promise.all([
      getStudentEnrollments(user.id),
      getStudentAssignments(user.id),
      getStudentProgress(user.id),
    ]).then(([e, a, p]) => {
      setEnrollments(e.data);
      setAssignments(a.data);
      setProgress(p.data);
    }).finally(() => setLoading(false));
  }, [user.id]);

  if (loading) return <Spinner />;

  const pending = assignments.filter(a => !a.submission_status || a.submission_status === 'Not Submitted');
  const late    = assignments.filter(a => a.submission_status === 'Late');
  const weakAreas = progress.filter(p => p.weak_area);

  return (
    <div className="p-6 max-w-5xl">
      {/* Greeting */}
      <div className="mb-6">
        <h1 className="text-xl font-medium text-gray-900">Good day, {user.name.split(' ')[0]}</h1>
        <p className="text-sm text-gray-400 mt-0.5">Here's your learning overview</p>
      </div>

      {/* Metrics */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
        <MetricCard label="Courses enrolled" value={enrollments.length} />
        <MetricCard label="Pending assignments" value={pending.length} sub={late.length > 0 ? `${late.length} late` : undefined} />
        <MetricCard label="Topics completed" value={progress.filter(p => p.is_completed).length} sub={`of ${progress.length}`} />
        <MetricCard label="Avg score" value={
          progress.filter(p => p.score).length
            ? Math.round(progress.reduce((s, p) => s + (p.score || 0), 0) / progress.filter(p => p.score).length) + '%'
            : '—'
        } />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* My Courses */}
        <Card>
          <SectionTitle>My courses</SectionTitle>
          <div className="flex flex-col divide-y divide-gray-50">
            {enrollments.map(e => {
              const pct = e.total_topics > 0 ? Math.round((e.completed_topics / e.total_topics) * 100) : 0;
              return (
                <div key={e.enrollment_id} className="py-3 first:pt-0 last:pb-0">
                  <div className="flex items-center justify-between mb-1">
                    <div>
                      <span className="text-sm font-medium text-gray-800">{e.course_name}</span>
                      <span className="text-xs text-gray-400 ml-2">{e.course_code}</span>
                    </div>
                    <Badge label={e.difficulty_level} variant={
                      { Beginner:'green', Intermediate:'amber', Advanced:'red' }[e.difficulty_level]
                    } />
                  </div>
                  <ProgressBar pct={pct} />
                  <p className="text-xs text-gray-400 mt-1">{pct}% complete · {e.teacher_name}</p>
                </div>
              );
            })}
          </div>
        </Card>

        {/* AI Suggestions */}
        <Card>
          <SectionTitle>AI tutor suggestions</SectionTitle>
          {weakAreas.length === 0 ? (
            <p className="text-sm text-gray-400">No weak areas identified yet. Keep learning!</p>
          ) : (
            <div className="flex flex-col gap-3">
              {weakAreas.slice(0, 3).map(p => (
                <div key={p.progress_id} className="border-l-2 border-teal-400 pl-3 py-1">
                  <p className="text-xs font-medium text-teal-600">{p.course_code} · {p.topic_name}</p>
                  <p className="text-xs text-gray-500 mt-0.5">Weak area: {p.weak_area}</p>
                  {p.ai_suggestion && (
                    <p className="text-xs text-gray-400 mt-1 italic">{p.ai_suggestion}</p>
                  )}
                </div>
              ))}
            </div>
          )}
        </Card>

        {/* Upcoming assignments */}
        <Card>
          <SectionTitle>Assignments</SectionTitle>
          <div className="flex flex-col divide-y divide-gray-50">
            {assignments.slice(0, 5).map(a => (
              <div key={a.assignment_id} className="flex items-center justify-between py-2.5 first:pt-0 last:pb-0">
                <div>
                  <p className="text-sm text-gray-800">{a.title}</p>
                  <p className="text-xs text-gray-400">{a.course_code} · Due {new Date(a.due_date).toLocaleDateString()}</p>
                </div>
                <div className="flex items-center gap-2">
                  {a.grade && <Badge label={a.grade} variant={gradeVariant(a.grade)} />}
                  <Badge
                    label={a.submission_status || 'Pending'}
                    variant={
                      a.submission_status === 'Submitted' ? 'green'
                      : a.submission_status === 'Late'     ? 'red'
                      : 'amber'
                    }
                  />
                </div>
              </div>
            ))}
          </div>
        </Card>

        {/* Recent progress */}
        <Card>
          <SectionTitle>Recent topic activity</SectionTitle>
          <div className="flex flex-col divide-y divide-gray-50">
            {progress.slice(0, 5).map(p => (
              <div key={p.progress_id} className="flex items-center justify-between py-2.5 first:pt-0 last:pb-0">
                <div>
                  <p className="text-sm text-gray-800">{p.topic_name}</p>
                  <p className="text-xs text-gray-400">{p.course_name}</p>
                </div>
                <div className="flex items-center gap-2">
                  {p.score != null && (
                    <span className="text-xs font-medium text-gray-600">{p.score}%</span>
                  )}
                  <Badge label={p.is_completed ? 'Done' : 'In progress'} variant={p.is_completed ? 'green' : 'amber'} />
                </div>
              </div>
            ))}
          </div>
        </Card>
      </div>
    </div>
  );
}
